:root {
        color-scheme: dark;
        color: #eee;
        background: #121212;
      }

      * {
        box-sizing: border-box;
      }

      body {
        min-width: 280px;
        margin: 0;
        background: #121212;
      }

      .message-list {
        width: 100%;
        max-width: 960px;
        margin: 0 auto;
        padding: 0 24px 48px;
      }

      .log-title {
        margin: 24px 0;
        font-size: 24px;
      }

      .message {
        display: grid;
        grid-template-columns: 40px minmax(0, 1fr);
        column-gap: 12px;
        padding: 16px 0;
        border-bottom: 1px solid #262626;
      }

      .message.system {
        display: block;
        padding-left: 52px;
        color: #888;
      }

      .avatar,
      .avatar-spacer {
        width: 40px;
        height: 40px;
      }

      .avatar {
        display: block;
        background-repeat: no-repeat;
        background-size: 100% 100%;
      }


      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      

      


      .message-content {
        min-width: 0;
      }

      .message-header {
        display: flex;
        align-items: baseline;
        flex-wrap: wrap;
        gap: 8px;
      }

      .speaker {
        color: var(--speaker-color);
        font-size: 14px;
        font-weight: bold;
      }

      .timestamp,
      .edited,
      .channel-name {
        color: #888;
        font-size: 12px;
      }

      .message-text,
      .roll-result {
        font-size: 16px;
        line-height: 1.6;
        overflow-wrap: anywhere;
        white-space: pre-wrap;
      }

      .roll-result {
        display: block;
        color: #888;
      }

      .roll-result.success,
      .roll-result.critical {
        color: #2196f3;
      }

      .roll-result.failure,
      .roll-result.fumble {
        color: #dc004e;
      }

